/**
 * The shipped FPS dataset.
 *
 * `data/catalog.json` is generated by `npm run games:data` from two public
 * bases (see the script for the exact provenance) and bundled with the app, so
 * the page works offline and never depends on a server being up.
 *
 * The file is compact arrays, not objects: 17k games of named fields would be
 * several megabytes for no benefit. Everything is validated on load - a record
 * that does not have the shape the code expects is dropped, because a shifted
 * column would produce a plausible-looking lie.
 *
 * Two lookups are pre-computed here: games by folded name (accent- and
 * case-insensitive search) and GPUs by a canonical form that ignores vendor
 * words but keeps "Ti", "SUPER", "Laptop" and memory sizes, which are exactly
 * the tokens that decide performance.
 */

import catalog from './data/catalog.json'
import type {
  GameDataSource,
  GamePreset,
  GameResolution,
  GameUpscaling,
  GpuMatch
} from '@shared/features/games'

/** One game as published: 1080p/High FPS on each reference GPU, in order. */
export interface DatasetGame {
  name: string
  year?: number
  /** Engine frame cap; 0 when the game has none. */
  cap: number
  /** FPS at 1080p/High on each of the reference GPUs. */
  fps: number[]
}

export interface DatasetReference {
  id: string
  name: string
  g3d: number
}

export interface MeasuredRun {
  game: string
  gpu: string
  resolution: GameResolution
  preset: GamePreset
  upscaling: GameUpscaling
  avg: number
  low1: number | null
  samples: number
  cpu?: string
  os?: string
  date?: string
  ref?: string
}

export interface Dataset {
  games: DatasetGame[]
  /** Games by folded name, for the search box. */
  byName: Map<string, DatasetGame>
  gpus: GpuMatch[]
  /** GPUs by canonical name, for matching the detected hardware. */
  gpusByCanonical: Map<string, GpuMatch>
  referenceGpus: DatasetReference[]
  measured: MeasuredRun[]
  /** Ceiling the estimates source applies to every published value. */
  sourceCap: number
  sources: GameDataSource[]
  generatedAt: string
  /** Records dropped by validation, per block. */
  dropped: { games: number; gpus: number; measured: number }
}

const RESOLUTIONS: GameResolution[] = ['1920x1080', '2560x1440', '3840x2160']
const PRESETS: GamePreset[] = ['Baixo', 'Médio', 'Alto', 'Ultra']
const UPSCALING: GameUpscaling[] = ['Native', 'Quality', 'Performance']

function isFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value)
}

/** Case- and accent-insensitive key: "Ragnarök" and "ragnarok" are the same. */
export function fold(text: string): string {
  return text
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim()
}

/**
 * Canonical GPU name.
 *
 * Vendor words carry no performance information and differ between the
 * detector ("NVIDIA GeForce RTX 4070") and the table ("GeForce RTX 4070"), so
 * they go. Everything else stays: "Ti", "SUPER", "Laptop", "Max-Q" and memory
 * sizes are the parts that separate a 4070 from a 4070 Ti.
 */
export function canonicalGpu(name: string): string {
  return fold(name)
    .replace(/\(r\)|\(tm\)|®|™/g, ' ')
    .replace(/\b(nvidia|geforce|amd|radeon|intel)\b/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()
    .replace(/\s+/g, ' ')
}

function tokens(value: string): string[] {
  return value.split(' ').filter(Boolean)
}

/** True when `part` appears as a contiguous run of tokens inside `whole`. */
function containsTokens(whole: string[], part: string[]): boolean {
  if (part.length === 0 || part.length > whole.length) return false
  for (let start = 0; start + part.length <= whole.length; start++) {
    let match = true
    for (let offset = 0; offset < part.length; offset++) {
      if (whole[start + offset] !== part[offset]) {
        match = false
        break
      }
    }
    if (match) return true
  }
  return false
}

/**
 * Match a name reported by the system against the GPU table.
 *
 * Exact canonical equality first, then the longest table name contained in
 * the detected name. The second rule is what makes "AD104 [GeForce RTX 4070]"
 * (a Linux string) land on the 4070 instead of failing; the longest wins so
 * "RTX 4070 Ti SUPER" is never read as "RTX 4070".
 */
export function matchGpu(dataset: Dataset, detected: string): GpuMatch | undefined {
  const key = canonicalGpu(detected)
  if (!key) return undefined

  const exact = dataset.gpusByCanonical.get(key)
  if (exact) return exact

  const detectedTokens = tokens(key)
  let best: GpuMatch | undefined
  let bestTokens = 0

  for (const gpu of dataset.gpus) {
    const candidate = tokens(canonicalGpu(gpu.name))
    if (candidate.length < bestTokens || candidate.length === 0) continue
    if (!containsTokens(detectedTokens, candidate)) continue
    // A single token has to be a model number with some substance, otherwise
    // "780" inside "gtx 780 ti" could match an unrelated card.
    if (candidate.length === 1 && candidate[0].length < 4) continue
    best = gpu
    bestTokens = candidate.length
  }

  return best
}

/** Fill the indexes, dropping anything that does not validate. */
export function normalizeDataset(raw: unknown): Dataset {
  const source = (raw ?? {}) as Record<string, unknown>
  const dropped = { games: 0, gpus: 0, measured: 0 }

  const referenceGpus: DatasetReference[] = []
  for (const item of Array.isArray(source.referenceGpus) ? source.referenceGpus : []) {
    const entry = item as Record<string, unknown>
    if (
      typeof entry.id !== 'string' ||
      typeof entry.name !== 'string' ||
      !isFiniteNumber(entry.g3d) ||
      entry.g3d <= 0
    ) {
      dropped.gpus++
      continue
    }
    referenceGpus.push({ id: entry.id, name: entry.name, g3d: entry.g3d })
  }
  referenceGpus.sort((a, b) => a.g3d - b.g3d)

  // The curve needs at least two anchors to say anything at all.
  if (referenceGpus.length < 2) {
    throw new Error('catalog.json: menos de duas GPUs de referência')
  }

  const gpus: GpuMatch[] = []
  const gpusByCanonical = new Map<string, GpuMatch>()
  for (const item of Array.isArray(source.gpus) ? source.gpus : []) {
    if (!Array.isArray(item) || item.length < 3) {
      dropped.gpus++
      continue
    }
    const [name, g3d, type] = item as [unknown, unknown, unknown]
    if (typeof name !== 'string' || !isFiniteNumber(g3d) || g3d <= 0) {
      dropped.gpus++
      continue
    }
    const gpu: GpuMatch = {
      name,
      g3d,
      type: typeof type === 'string' ? type : 'Unknown'
    }
    gpus.push(gpu)
    const canonical = canonicalGpu(name)
    if (canonical && !gpusByCanonical.has(canonical)) gpusByCanonical.set(canonical, gpu)
  }

  const games: DatasetGame[] = []
  const byName = new Map<string, DatasetGame>()
  for (const item of Array.isArray(source.games) ? source.games : []) {
    if (!Array.isArray(item) || item.length < 4) {
      dropped.games++
      continue
    }
    const [name, year, cap, fps] = item as [unknown, unknown, unknown, unknown]
    if (typeof name !== 'string' || !Array.isArray(fps) || fps.length !== referenceGpus.length) {
      dropped.games++
      continue
    }
    if (!fps.every((value) => isFiniteNumber(value) && value >= 0)) {
      dropped.games++
      continue
    }
    const game: DatasetGame = {
      name,
      year: isFiniteNumber(year) && year > 0 ? year : undefined,
      cap: isFiniteNumber(cap) && cap > 0 ? cap : 0,
      fps: fps as number[]
    }
    const key = fold(name)
    if (byName.has(key)) {
      dropped.games++
      continue
    }
    byName.set(key, game)
    games.push(game)
  }

  const measured: MeasuredRun[] = []
  for (const item of Array.isArray(source.measured) ? source.measured : []) {
    const entry = item as Record<string, unknown>
    if (
      typeof entry.game !== 'string' ||
      typeof entry.gpu !== 'string' ||
      !RESOLUTIONS.includes(entry.resolution as GameResolution) ||
      !PRESETS.includes(entry.preset as GamePreset) ||
      !UPSCALING.includes(entry.upscaling as GameUpscaling) ||
      !isFiniteNumber(entry.avg) ||
      entry.avg <= 0
    ) {
      dropped.measured++
      continue
    }
    measured.push({
      game: entry.game,
      gpu: entry.gpu,
      resolution: entry.resolution as GameResolution,
      preset: entry.preset as GamePreset,
      upscaling: entry.upscaling as GameUpscaling,
      avg: entry.avg,
      low1: isFiniteNumber(entry.low1) && entry.low1 > 0 ? entry.low1 : null,
      samples: isFiniteNumber(entry.samples) && entry.samples > 0 ? entry.samples : 1,
      cpu: typeof entry.cpu === 'string' ? entry.cpu : undefined,
      os: typeof entry.os === 'string' ? entry.os : undefined,
      date: typeof entry.date === 'string' ? entry.date : undefined,
      ref: typeof entry.ref === 'string' ? entry.ref : undefined
    })
  }

  const sources = (Array.isArray(source.sources) ? source.sources : []).filter(
    (item): item is GameDataSource =>
      typeof item === 'object' &&
      item !== null &&
      typeof (item as GameDataSource).id === 'string' &&
      typeof (item as GameDataSource).name === 'string' &&
      typeof (item as GameDataSource).license === 'string'
  )

  return {
    games,
    byName,
    gpus,
    gpusByCanonical,
    referenceGpus,
    measured,
    sourceCap: isFiniteNumber(source.sourceCap) && source.sourceCap > 0 ? source.sourceCap : 360,
    sources,
    generatedAt: typeof source.generatedAt === 'string' ? source.generatedAt : '',
    dropped
  }
}

let cache: Dataset | null = null

/** The bundled dataset, validated once and reused. */
export function getDataset(): Dataset {
  if (!cache) cache = normalizeDataset(catalog)
  return cache
}

/** Games whose name contains the query, plus how many matched in total. */
export function searchGames(
  dataset: Dataset,
  query: string,
  limit: number
): { items: DatasetGame[]; total: number } {
  const needle = fold(query)
  if (!needle) return { items: [], total: 0 }
  const matches = dataset.games.filter((game) => fold(game.name).includes(needle))
  return { items: matches.slice(0, limit), total: matches.length }
}

/** GPU table entries whose name contains the query, best matches first. */
export function searchGpus(dataset: Dataset, query: string, limit: number): GpuMatch[] {
  const needle = fold(query)
  if (!needle) return []
  const matches = dataset.gpus.filter((gpu) => fold(gpu.name).includes(needle))
  // Shorter names are usually the card itself ("GeForce RTX 4070") rather than
  // a laptop or memory variant, so they come first.
  matches.sort((a, b) => a.name.length - b.name.length)
  return matches.slice(0, limit)
}
